    auto simpson_rule = [](FunctionPtr f, double x0, double x1, double x2) -> double {
        return (x2 - x0) / 6.0 * (f(x0) + 4.0 * f(x1) + f(x2));
    };

    // Recursive helper function for adaptive Simpson
    std::function<double(FunctionPtr, double, double, double, double)> adaptive_simpson_helper;
    adaptive_simpson_helper = [&simpson_rule, &adaptive_simpson_helper](FunctionPtr f, double a, double b, double precision, double s) -> double {
        double c = (a + b) / 2.0;
        double h = (b - a) / 2.0;
        double x0 = a;
        double x1 = a + h / 2.0;
        double x2 = c;
        double x3 = c + h / 2.0;
        double x4 = b;

        double s1 = simpson_rule(f, x0, x1, x2);
        double s2 = simpson_rule(f, x2, x3, x4);

        // Error estimation
        double error = std::abs(s1 + s2 - s);
        if (error <= 15.0 * precision) {  // 15 is a safety factor
            return s1 + s2;
        } else {
            // Recurse on both halves
            double left = adaptive_simpson_helper(f, a, c, precision / 2.0, s1);
            double right = adaptive_simpson_helper(f, c, b, precision / 2.0, s2);
            return left + right;
        }
    };

    // Initial Simpson approximation
    double s = simpson_rule(f, a, (a + b) / 2.0, b);

    // Start the adaptive process
